    print(f"Pair {i}: '{inp}' -> '{outp}'")

    # Try to find minimal edit operations
    if inp != outp:
        # Find the difference
        min_len = min(len(inp), len(outp))
        diff_positions = []
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_positions.append((j, inp[j], outp[j]))

        if len(inp) != len(outp):
            if len(outp) > len(inp):
                added_chars = outp[len(inp):]
                print(f"  Added chars: '{added_chars}' at end")
            else:
                removed_chars = inp[len(outp):]
                print(f"  Removed chars: '{removed_chars}' at end")

        if diff_positions:
            print(f"  Differences at positions: {diff_positions}")
    print()

